// Builds the lesson inventory table from CURRICULUM.md (titles) and the lesson files (sources).
const fs = require("fs")
const dir = process.argv[2]
const cur = fs.readFileSync(dir + "/CURRICULUM.md", "utf8")
const bodies = fs.readFileSync(dir + "/LESSONS-FOUNDATIONS.md", "utf8") + "\n" + fs.readFileSync(dir + "/LESSONS-PRACTICE.md", "utf8")
const rows = [...cur.matchAll(/\| (C\d{2}-L\d+) ([^|]+?) \|/g)].map((m) => [m[1], m[2].trim()])
const seen = new Set()
const blocked = { C07: "BLOCKED (`AP-LEG-03`, `AP-COM-06`)", C11: "BLOCKED (agreement, terms); `PROPOSED POLICY`", C12: "BLOCKED (agreement, `AP-GOV-02`)" }
const result = {
  "C02-L6": "VERIFIED; source `ownerReview`",
  "C05-L3": "VERIFIED; source `ownerReview`",
  "C06-L2": "VERIFIED; `crm` source `ownerReview`; `AP-PROOF-01`",
  "C01-L2": "CORRECTED (full boundary text, VAT note)",
  "C03-L7": "REQUIRES FOUNDER DECISION (`AP-CNT-06`, new wording)",
  "C04-L3": "REQUIRES FOUNDER DECISION (`AP-COM-03`)",
  "C06-L5": "UNSUPPORTED as published wording (no FAQ key); consistent with faq:process-automation",
  "C07-L5": "REQUIRES LEGAL REVIEW (ICO/PECR summary)",
  "C10-L3": "VERIFIED; discounting rule `AP-COM-05`",
  "C11-L3": "CORRECTED (rounding scope, refund reversal)",
  "C11-L4": "CORRECTED (historical terms; illustration caveat); REQUIRES ACCOUNTING REVIEW",
  "C11-L5": "CORRECTED (market default wording)",
  "C12-L1": "REQUIRES LEGAL REVIEW (employment status)",
  "C12-L2": "REQUIRES FOUNDER DECISION (`AP-GOV-05`)",
  "C12-L5": "REQUIRES PRIVACY REVIEW (`AP-PRIV-01`)",
  "C13-L4": "REQUIRES FOUNDER DECISION (attribution standard)",
  "C01-L4": "REQUIRES LEGAL REVIEW (`AP-GOV-01`)",
  "C01-L6": "DEFERRED (describes B1 software not yet built)",
  "C10-L8": "DEFERRED (describes B1 software not yet built)",
}
const out = ["| Lesson | Title | Sources cited | Review result |", "|---|---|---|---|"]
for (const [id, title] of rows) {
  if (seen.has(id)) continue
  seen.add(id)
  const start = bodies.indexOf("### " + id + " ")
  const end = bodies.indexOf("\n### ", start + 4)
  const body = bodies.slice(start, end < 0 ? undefined : end)
  const src = (body.match(/\*\*Sources?:\*\*\s*([^\n]*)/) || [])[1]
  const srcText = src ? src.replace(/\|/g, "/").replace(/\.\s.*$/, "").slice(0, 90) : "none (draft guidance)"
  const course = id.slice(0, 3)
  const res = result[id] || (blocked[course] ? blocked[course] : src ? "VERIFIED against cited sources" : "DRAFT guidance; no factual claim needing a source")
  out.push(`| ${id} | ${title} | ${srcText} | ${res} |`)
}
console.log(out.join("\n"))
console.error("rows:", seen.size)
